(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory(root);
  else root.PianoKeyboard = factory(root);
})(this, function (root) {
  var WHITE_W = 48;
  var BLACK_W = 30;

  function isBlack(midi) {
    return [1, 3, 6, 8, 10].indexOf(midi % 12) !== -1;
  }

  function noteName(midi) {
    var names = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
    var n = root.PianoNotes || (typeof require === 'function' ? require('./notes.js') : null);
    if (n && n.noteName) return n.noteName(midi);
    return names[midi % 12] + (Math.floor(midi / 12) - 1);
  }

  function render(container, keyMap, handlers) {
    var doc = container.ownerDocument;
    var keys = {};
    var whites = 0;

    keyMap.forEach(function (b) {
      var el = doc.createElement('div');
      var black = isBlack(b.midi);
      el.className = 'key ' + (black ? 'black' : 'white');
      el.setAttribute('data-midi', String(b.midi));

      var name = doc.createElement('span');
      name.className = 'note';
      name.textContent = noteName(b.midi);
      var letter = doc.createElement('span');
      letter.className = 'letter';
      letter.textContent = b.computerKey.toUpperCase();
      el.appendChild(name);
      el.appendChild(letter);

      if (black) {
        el.style.left = (whites * WHITE_W - BLACK_W / 2) + 'px';
      } else {
        whites++;
      }

      var held = {};
      el.addEventListener('pointerdown', function (e) {
        if (e.button !== 0) return;
        e.preventDefault();
        held[e.pointerId] = true;
        handlers.onPress(b.midi, 'pointer:' + e.pointerId);
      });
      function release(e) {
        if (!held[e.pointerId]) return;
        delete held[e.pointerId];
        handlers.onRelease(b.midi, 'pointer:' + e.pointerId);
      }
      el.addEventListener('pointerup', release);
      el.addEventListener('pointerleave', release);
      el.addEventListener('pointercancel', release);

      container.appendChild(el);
      keys[b.midi] = el;
    });

    return {
      setActive: function (midi, on) {
        var el = keys[midi];
        if (el) el.classList.toggle('active', !!on);
      }
    };
  }

  return { render: render };
});
