(function () {
  var N = window.PianoNotes;
  var ERROR_TEXT = 'Your browser cannot play sound (Web Audio is not available).';
  var errorEl = document.getElementById('error');
  var select = document.getElementById('waveform');
  var canvas = document.getElementById('scope');
  var readout = document.getElementById('note-name');

  var AudioCtor = window.AudioContext || window.webkitAudioContext;
  var ctx = null;
  var synth = null;
  var audioFailed = false;
  var scope = null;

  var holders = new Map(); // midi -> Set of sources
  var order = []; // midi in press order

  function showError() {
    errorEl.textContent = ERROR_TEXT;
    errorEl.hidden = false;
  }

  function startScope(analyser) {
    if (scope) scope.stop();
    scope = window.PianoScope.createScope(canvas, analyser);
    scope.start();
  }

  function ensureAudio() {
    if (audioFailed) return;
    try {
      if (!ctx) {
        if (!AudioCtor) throw new Error('no Web Audio');
        ctx = new AudioCtor();
        synth = window.PianoSynth.createSynth(ctx);
        synth.setWaveform(select.value);
        startScope(synth.analyser);
      }
      if (ctx.state === 'suspended') {
        var p = ctx.resume();
        if (p && p.catch) p.catch(function () { audioFailed = true; showError(); });
      }
    } catch (err) {
      audioFailed = true;
      synth = null;
      showError();
    }
  }

  function updateReadout() {
    readout.textContent = N.displayText(order.map(N.noteName));
  }

  var keyboard = window.PianoKeyboard.render(
    document.getElementById('keyboard'),
    N.KEY_MAP,
    {
      onPress: function (midi, source) { press(midi, source); },
      onRelease: function (midi, source) { release(midi, source); }
    }
  );

  function press(midi, source) {
    ensureAudio();
    var set = holders.get(midi);
    if (!set) {
      set = new Set();
      holders.set(midi, set);
    }
    var first = set.size === 0;
    set.add(source);
    if (!first) return;
    order.push(midi);
    if (synth) synth.noteOn(midi, N.frequency(midi));
    keyboard.setActive(midi, true);
    updateReadout();
  }

  function release(midi, source) {
    var set = holders.get(midi);
    if (!set || !set.delete(source)) return;
    if (set.size > 0) return;
    holders.delete(midi);
    order.splice(order.indexOf(midi), 1);
    if (synth) synth.noteOff(midi);
    keyboard.setActive(midi, false);
    updateReadout();
  }

  function releaseAll() {
    if (synth) synth.allOff();
    order.forEach(function (m) { keyboard.setActive(m, false); });
    holders.clear();
    order = [];
    updateReadout();
  }

  window.addEventListener('keydown', function (e) {
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    var note = N.noteForKey(e.key);
    if (!note) return;
    e.preventDefault();
    if (e.repeat) return;
    press(note.midi, 'key:' + e.key.toLowerCase());
  });

  window.addEventListener('keyup', function (e) {
    var note = N.noteForKey(e.key);
    if (!note) return;
    e.preventDefault();
    release(note.midi, 'key:' + e.key.toLowerCase());
  });

  select.addEventListener('change', function () {
    if (synth) synth.setWaveform(select.value);
  });

  window.addEventListener('blur', releaseAll);
  document.addEventListener('visibilitychange', function () {
    if (document.hidden) releaseAll();
  });

  if (!AudioCtor) showError();
  startScope(null);
})();
