const test = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');
const { execFileSync } = require('node:child_process');

const root = path.join(__dirname, '..');
const html = fs.readFileSync(path.join(root, 'index.html'), 'utf8');

function walk(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) =>
    e.isDirectory() ? walk(path.join(dir, e.name)) : [path.join(dir, e.name)]);
}

test('required ids exist', () => {
  for (const id of ['waveform', 'scope', 'note-name', 'keyboard', 'error']) {
    assert.match(html, new RegExp('id="' + id + '"'), id);
  }
});

test('scripts load in order', () => {
  const srcs = [...html.matchAll(/<script src="([^"]+)"/g)].map((m) => m[1]);
  assert.deepStrictEqual(srcs, ['js/notes.js', 'js/synth.js', 'js/scope.js', 'js/keyboard.js', 'js/app.js']);
});

test('no modules', () => {
  assert.doesNotMatch(html, /type=["']?module/);
});

test('no http(s) urls', () => {
  const files = [path.join(root, 'index.html'), ...walk(path.join(root, 'css')), ...walk(path.join(root, 'js'))];
  for (const f of files) {
    assert.doesNotMatch(fs.readFileSync(f, 'utf8'), /https?:\/\//, f);
  }
});

test('referenced files exist', () => {
  const refs = [...html.matchAll(/(?:src|href)="([^"]+)"/g)].map((m) => m[1]);
  assert.ok(refs.length >= 6);
  for (const r of refs) assert.ok(fs.existsSync(path.join(root, r)), r);
});

test('select has 4 options', () => {
  const sel = html.match(/<select id="waveform"[\s\S]*?<\/select>/)[0];
  assert.strictEqual((sel.match(/<option/g) || []).length, 4);
  assert.match(sel, /value="sine" selected/);
});

test('keyboard.js and app.js parse', () => {
  for (const f of ['js/keyboard.js', 'js/app.js']) {
    execFileSync(process.execPath, ['--check', path.join(root, f)]);
  }
});

test('keyboard.js loads in node', () => {
  assert.strictEqual(typeof require('../js/keyboard.js').render, 'function');
});
