  const log = [];
  const ctxs = [];
  function node() { return { connect() {}, disconnect() {}, gain: { setValueAtTime() {}, linearRampToValueAtTime() {}, exponentialRampToValueAtTime() {}, cancelScheduledValues() {}, value: 0 }, frequency: {}, start() { log.push(['start']); }, stop() { log.push(['stop']); }, getFloatTimeDomainData() {}, fftSize: 2048 }; }
